#[cfg(all(test, not(target_arch = "wasm32")))]
mod tests {
    use std::collections::BTreeMap;
    use std::path::Path;
    use std::sync::Arc;

    use async_graphql::{Request, Variables};
    use futures_lite::future::block_on;
    use serde_json::json;

    fn position_value() -> serde_json::Value {
        json!({
            "center": { "u": 0.0, "v": 0.0 },
            "plane": {
                "origin": { "x": 0.0, "y": 0.0, "z": 0.0 },
                "xAxis":  { "x": 1.0, "y": 0.0, "z": 0.0 },
                "yAxis":  { "x": 0.0, "y": 1.0, "z": 0.0 }
            }
        })
    }

    fn create_fixed_piece_vars(design_id: &str) -> async_graphql::Value {
        async_graphql::value!({
            "draftId": "d1",
            "txId": "t1",
            "designId": design_id,
            "position": position_value()
        })
    }

    const CREATE_FIXED_PIECE: &str = r#"
        mutation($draftId: ID!, $txId: ID!, $designId: ID!, $position: PositionInput!) {
            createFixedPiece(draftId: $draftId, transactionId: $txId, designId: $designId, position: $position)
        }
    "#;

    /// 📤 Writes the generated SDL to `COMPOSE_GRAPHQL_SCHEMA_OUT`; run via `npx nx build compose/graphql`.
    #[test]
    #[ignore = "writes the generated SDL to COMPOSE_GRAPHQL_SCHEMA_OUT"]
    fn export_compose_graphql_schema_file() {
        let out = std::env::var("COMPOSE_GRAPHQL_SCHEMA_OUT").expect("COMPOSE_GRAPHQL_SCHEMA_OUT");
        let path = std::path::PathBuf::from(out);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).expect("create schema output parent");
        }
        std::fs::write(path, block_on(crate::gql::sdl())).expect("write generated GraphQL schema");
    }

    #[test]
    fn parses_target_schema() {
        let sdl = block_on(crate::gql::sdl());
        for t in [
            "type Query",
            "type Mutation",
            "type Piece",
            "type Connector",
            "type Port",
            "type Connection",
            "type Design",
            "type Kit",
            "type Graph",
            "type Session",
            "type Conflict",
            "type Checkpoint",
            "type Alternative",
            "type Draft",
            "type Transaction",
            "type Change",
            "type CreatedFixedPiece",
            "interface Operation",
            "scalar Timestamp",
        ] {
            assert!(sdl.contains(t), "schema missing `{}`", t);
        }
    }

    /// 🛡️ Guard test: the crate must contain exactly **one** `pub async fn emit_event` definition.
    #[test]
    fn single_emit_event_in_codebase() {
        let src = include_str!("lib.rs");
        let needle = concat!("pub async fn ", "emit_event(&self, ev: Event)");
        let count = src.matches(needle).count();
        assert_eq!(count, 1, "expected exactly one canonical emit_event definition in lib.rs, found {}", count);
    }

    #[test]
    fn create_fixed_piece_end_to_end() {
        block_on(async {
            let schema = crate::gql::build_schema().await;
            let res = schema.execute(Request::new(CREATE_FIXED_PIECE).variables(Variables::from_value(create_fixed_piece_vars("des1")))).await;
            assert!(res.errors.is_empty(), "mutation errors: {:?}", res.errors);

            // The wip child applies asynchronously; wait briefly for the event loop.
            std::thread::sleep(std::time::Duration::from_millis(150));

            let q = "{ wip { theKit { designs { id pieces { id position { center { u } } } } } } }";
            let res = schema.execute(q).await;
            assert!(res.errors.is_empty(), "query errors: {:?}", res.errors);
            let data = res.data.into_json().unwrap();
            let designs = &data["wip"]["theKit"]["designs"];
            assert!(designs.as_array().map(|a| a.iter().any(|d| !d["pieces"].as_array().unwrap().is_empty())).unwrap_or(false), "expected at least one piece in wip; got: {}", serde_json::to_string_pretty(&data).unwrap());
        });
    }

    #[test]
    fn wip_and_authoritative_are_isolated() {
        block_on(async {
            let schema = crate::gql::build_schema().await;
            let _ = schema.execute(Request::new(CREATE_FIXED_PIECE).variables(Variables::from_value(create_fixed_piece_vars("des1")))).await;
            std::thread::sleep(std::time::Duration::from_millis(150));

            let q = "{ authoritative { theKit { designs { pieces { id } } } } }";
            let res = schema.execute(q).await;
            let data = res.data.into_json().unwrap();
            let designs = &data["authoritative"]["theKit"]["designs"];
            assert!(designs.as_array().map(|a| a.iter().all(|d| d["pieces"].as_array().unwrap().is_empty())).unwrap_or(true), "authoritative leaked pieces: {}", serde_json::to_string_pretty(&data).unwrap());
        });
    }

    /// 🛡️ Traversal must share Arcs, not deep-copy entities. Resolves a deep path and asserts
    /// the live `Arc<Piece>` strong count grows only by the bounded number of resolver hops
    /// that touch it (not by the number of pieces in the design).
    #[test]
    fn no_deep_clone_on_traversal() {
        block_on(async {
            let rt = crate::worker::ParentRuntime::spawn().await;
            let bus = rt.bus.clone();

        pub the_kit: Arc<Kit>,
        pub alternatives: RwLock<Vec<Arc<Alternative>>>,
        pub checkpoints: RwLock<Vec<Arc<Checkpoint>>>,
        pub releases: RwLock<Vec<Arc<Checkpoint>>>,
        pub drafts: RwLock<Vec<Arc<Draft>>>,
    }

    impl Default for Graph {
        fn default() -> Self {
            Self { id: Id::default(), owner_session: Weak::new(), the_kit: Arc::default(), alternatives: RwLock::new(Vec::new()), checkpoints: RwLock::new(Vec::new()), releases: RwLock::new(Vec::new()), drafts: RwLock::new(Vec::new()) }
        }
    }

    impl Graph {
        /// 🆕 Build a brand-new Graph wired with its `the_kit` Arc; `Kit::owner_graph` Weak is set
        /// in a second pass via [`Arc::new_cyclic`]-style assembly because both directions need an Arc.
        pub async fn new() -> Arc<Self> {
            let id = Id::new().await;
            Arc::new_cyclic(|weak_self: &Weak<Graph>| {
                let kit = crate::kit::Kit::new_sync(weak_self.clone(), "the kit".to_string());
                Self { id, owner_session: Weak::new(), the_kit: kit, alternatives: RwLock::new(Vec::new()), checkpoints: RwLock::new(Vec::new()), releases: RwLock::new(Vec::new()), drafts: RwLock::new(Vec::new()) }
            })
        }

        pub async fn compute_hash(&self) -> String {
            h(&[self.id.as_str()])
        }

        pub async fn ensure_draft(self: &Arc<Self>, draft_id: &Id) -> Arc<Draft> {
            if let Some(d) = self.drafts.read().await.iter().find(|d| &d.id == draft_id).cloned() {
                return d;
            }
            let d = Draft::with_id(draft_id.clone()).await;
            self.drafts.write().await.push(d.clone());
            d
        }

        /// 🪡 The single graph-mutating entry point for `createFixedPiece`. Returns the new Arc<Piece>.
        pub async fn apply_create_fixed_piece(
            self: &Arc<Self>,
            draft_id: Id,
            transaction_id: Id,
            design_id: Id,
            blueprint_id: Id,
            position: crate::geom::Position,
            name: Option<String>,
            description: Option<String>,
        ) -> Result<Arc<crate::kit::design::piece::Piece>, ComposeError> {
            let design: Arc<crate::kit::design::Design> = self.the_kit.ensure_design(&design_id).await;

            // Mint a placeholder Type as the Piece's blueprint reference (kept as Arc inside Blueprint::Type).
            let blueprint_type = crate::kit::r#type::Type::new(Arc::downgrade(&self.the_kit), format!("type-{}", blueprint_id.as_str())).await;
            let blueprint = crate::kit::r#type::Blueprint::Type(blueprint_type);

            let piece = crate::kit::design::piece::Piece::new_fixed(Arc::downgrade(&design), blueprint, position).await;
            piece.set_name(name).await;
            piece.set_description(description).await;
            let _ = design.insert_piece(piece.clone()).await;

            let draft = self.ensure_draft(&draft_id).await;
            let _ = draft.ensure_transaction(&transaction_id).await;

            Ok(piece)
        }
    }

    #[Object(name = "Graph")]
    impl Graph {
        async fn id(&self) -> Id {
            self.id.clone()
        }
        async fn hash(&self) -> String {
            self.compute_hash().await
        }
        async fn owner(&self) -> Option<Arc<Session>> {
            self.owner_session.upgrade()
        }
        #[graphql(name = "theKit")]
        async fn the_kit(&self) -> Option<Arc<Kit>> {
            Some(self.the_kit.clone())
        }
        async fn alternative(&self, id: Id) -> Option<Arc<Alternative>> {
            self.alternatives.read().await.iter().find(|a| a.id == id).cloned()
        }
        async fn alternatives(&self) -> Vec<Arc<Alternative>> {
            self.alternatives.read().await.clone()
        }
        async fn checkpoint(&self, id: Id) -> Option<Arc<Checkpoint>> {
            self.checkpoints.read().await.iter().find(|c| c.id == id).cloned()
        }
        async fn checkpoints(&self) -> Vec<Arc<Checkpoint>> {
            self.checkpoints.read().await.clone()
        }
        async fn release(&self, id: Id) -> Option<Arc<Checkpoint>> {
            self.releases.read().await.iter().find(|c| c.id == id).cloned()
        }
        async fn releases(&self) -> Vec<Arc<Checkpoint>> {
            self.releases.read().await.clone()
        }
    }
    //#endregion 🌐 graph

