    #[derive(Clone, Copy, Debug, Default, PartialEq, Serialize, Deserialize, SimpleObject, InputObject)]
    #[graphql(name = "Plane", input_name = "PlaneInput")]
    pub struct Plane {
        pub origin: Point,
        #[graphql(name = "xAxis")]
        pub x_axis: Vector,
        #[graphql(name = "yAxis")]
        pub y_axis: Vector,
    }

    #[derive(Clone, Copy, Debug, Default, PartialEq, Serialize, Deserialize, SimpleObject, InputObject)]
