//#region 📣 event

pub mod event {
    //! 📣 The single emit point of the entire crate. Variants carry Arc-shared payloads.
    use std::sync::Arc;

    use async_broadcast::{InactiveReceiver, Receiver, Sender};
    use async_lock::Mutex;

    use crate::error::ComposeError;
    use crate::op;

    /// 🌐 Broadcast envelope for every observable thing the control plane emits.
    #[derive(Clone)]
    pub enum Event {
        CommandSucceeded(op::CommandReceipt),
        OperationSucceeded(op::OperationKind),
        OperationFailed(ComposeError),
        CreatedFixedPiece(Arc<op::CreatedFixedPiece>),
        FixedPiece(Arc<op::FixedPiece>),
        DraggedPiece(Arc<op::DraggedPiece>),
        RenamedKit(Arc<op::RenamedKit>),
        ChangedDescription(Arc<op::ChangedDescription>),
    }

    /// 📣 The bus. Holds the only `emit_event` function in the crate.
    pub struct EventBus {
        tx: Mutex<Sender<Event>>,
        keep_alive: InactiveReceiver<Event>,
    }

    impl EventBus {
        pub fn new(capacity: usize) -> Arc<Self> {
            let (mut tx, rx) = async_broadcast::broadcast(capacity);
            tx.set_overflow(true);
            // No active receivers? still proceed (drop the message) instead of awaiting one.
            tx.set_await_active(false);
            Arc::new(Self { tx: Mutex::new(tx), keep_alive: rx.deactivate() })
        }

        /// 📣 The **only** `emit_event` in the entire crate. All other code paths must call this.
        pub async fn emit_event(&self, ev: Event) {
            let tx = self.tx.lock().await;
            let _ = tx.broadcast_direct(ev).await;
        }

        /// 🔔 New subscriber receiver.
        pub fn subscribe(&self) -> Receiver<Event> {
            self.keep_alive.activate_cloned()
        }
    }
}

//#endregion 📣 event

//#region 🧵 worker

pub mod worker {
    //! 🧵 Parent router + two child runtimes (wip + authoritative).
    //!
    //! Native: both children are spawned on `std::thread + futures-lite::block_on`.
    //! Wasm: each child lives in a dedicated [`web_sys::Worker`]; messages cross via [`crate::wasm_bridge`].
    use std::sync::Arc;

    use async_channel::{Receiver, Sender};
    use async_lock::RwLock;

    use crate::error::ComposeError;
    use crate::event::{Event, EventBus};
    use crate::id::Id;
    use crate::op::{Command, CommandReceipt, CreatedFixedPiece, CreatedFixedPieceInput};
    use crate::vcs::{Conflict, Graph, Session};

    /// 🚪 Per-child handle held by the parent: send commands in (events flow through the shared bus).
    pub struct ChildPort {
        inbound: Sender<Command>,
    }

    impl ChildPort {
        pub async fn send(&self, cmd: Command) {
            let _ = self.inbound.send(cmd).await;
        }
    }

    /// 🛰️ Parent runtime hosting the GraphQL schema + routing logic.
    pub struct ParentRuntime {
        pub bus: Arc<EventBus>,
        pub wip: ChildPort,
        pub auth: ChildPort,
        pub wip_graph: Arc<Graph>,
        pub auth_graph: Arc<Graph>,
        pub sessions: RwLock<Vec<Arc<Session>>>,
        pub conflicts: RwLock<Vec<Arc<Conflict>>>,
    }

    impl ParentRuntime {
        /// 🛰️ Spawn parent + two child runtimes (in-process on native).
        pub async fn spawn() -> Arc<Self> {
            let bus = EventBus::new(1024);

            let wip_graph = Graph::new().await;
            let auth_graph = Graph::new().await;

            let (wip_tx, wip_rx) = async_channel::unbounded::<Command>();
            let (auth_tx, auth_rx) = async_channel::unbounded::<Command>();

            spawn_child("wip", wip_graph.clone(), bus.clone(), wip_rx);
            spawn_child("auth", auth_graph.clone(), bus.clone(), auth_rx);

            Arc::new(Self { bus, wip: ChildPort { inbound: wip_tx }, auth: ChildPort { inbound: auth_tx }, wip_graph, auth_graph, sessions: RwLock::new(Vec::new()), conflicts: RwLock::new(Vec::new()) })
        }

        pub async fn dispatch_wip(&self, cmd: Command) -> Id {
            let id = cmd.request_id().clone();
            self.wip.send(cmd).await;
            id
        }

        pub async fn dispatch_auth(&self, cmd: Command) -> Id {
            let id = cmd.request_id().clone();
            self.auth.send(cmd).await;
            id
        }
    }

    fn spawn_child(label: &'static str, graph: Arc<Graph>, bus: Arc<EventBus>, inbox: Receiver<Command>) {
        let fut = async move { ChildRuntime { label, graph, bus, inbox }.run().await };
        #[cfg(target_arch = "wasm32")]
        {
            wasm_bindgen_futures::spawn_local(fut);
        }
        #[cfg(not(target_arch = "wasm32"))]
        {
            std::thread::spawn(move || futures_lite::future::block_on(fut));
        }
    }

    /// 🧵 In-worker actor: drains the inbox, applies, emits.
    pub struct ChildRuntime {
        pub label: &'static str,
        pub graph: Arc<Graph>,
        pub bus: Arc<EventBus>,
        pub inbox: Receiver<Command>,
    }

    impl ChildRuntime {
        pub async fn run(self) {
            while let Ok(cmd) = self.inbox.recv().await {
                let request_id = cmd.request_id().clone();
                let kind = match &cmd {
                    Command::CreateFixedPiece { .. } => "createFixedPiece",
                    Command::FixPiece { .. } => "fixPiece",
                    Command::RenameKit { .. } => "renameKit",
                    Command::ChangeDescription { .. } => "changeDescription",
                };
                self.bus.emit_event(Event::CommandSucceeded(CommandReceipt { request_id: request_id.clone(), kind: kind.to_string() })).await;

                if let Err(e) = self.apply(cmd).await {
                    let err = e.with_request(request_id);
                    self.bus.emit_event(Event::OperationFailed(err)).await;
                }
            }
        }

        async fn apply(&self, cmd: Command) -> Result<(), ComposeError> {
            match cmd {
                Command::CreateFixedPiece { request_id: _, draft_id, transaction_id, design_id, blueprint_id, position, name, description } => {
                    let piece = self.graph.apply_create_fixed_piece(draft_id, transaction_id, design_id.clone(), blueprint_id.clone(), position, name.clone(), description.clone()).await?;

                    let input = CreatedFixedPieceInput { design_id, blueprint_id, position, name, description };
                    let op = CreatedFixedPiece::new(input, piece).await;
                    self.bus.emit_event(Event::CreatedFixedPiece(op)).await;
                    Ok(())
                }
                Command::FixPiece { .. } | Command::RenameKit { .. } | Command::ChangeDescription { .. } => {
                    // Skeleton stubs — wired through commandSucceeded only.
                    Ok(())
                }
            }
        }
    }
}

//#endregion 🧵 worker

//#region 🌐 gql

pub mod gql {
    //! 🌐 GraphQL roots: Query / Mutation / Subscription + schema builder.
    use std::sync::Arc;

    use async_graphql::{Context, EmptySubscription, Object, Schema, Subscription};
    use async_stream::stream;
    use futures_util::Stream;

    use crate::error::ComposeError;
    use crate::event::{Event, EventBus};
    use crate::geom::Position;
    use crate::id::Id;
    use crate::op::{ChangedDescription, Command, CommandReceipt, CreatedFixedPiece, DraggedPiece, FixedPiece, OperationIface, RenamedKit};
    use crate::vcs::{Conflict, Graph, Session};
    use crate::worker::ParentRuntime;

    fn rt<'a>(ctx: &'a Context<'_>) -> async_graphql::Result<&'a Arc<ParentRuntime>> {
        ctx.data::<Arc<ParentRuntime>>()
    }
    fn bus<'a>(ctx: &'a Context<'_>) -> async_graphql::Result<&'a Arc<EventBus>> {
        ctx.data::<Arc<EventBus>>()
    }

    pub struct Query;

    #[Object]
    impl Query {
        async fn session(&self, ctx: &Context<'_>) -> async_graphql::Result<Arc<Session>> {
            let rt = rt(ctx)?;
            {
                let sessions = rt.sessions.read().await;
                if let Some(s) = sessions.first() {
                    return Ok(s.clone());
                }
            }
            let s = Session::new().await;
            rt.sessions.write().await.push(s.clone());
            Ok(s)
        }

        async fn wip(&self, ctx: &Context<'_>) -> async_graphql::Result<Arc<Graph>> {
            Ok(rt(ctx)?.wip_graph.clone())
        }

        async fn authoritative(&self, ctx: &Context<'_>) -> async_graphql::Result<Option<Arc<Graph>>> {
            Ok(Some(rt(ctx)?.auth_graph.clone()))
        }

        async fn conflicts(&self, ctx: &Context<'_>) -> async_graphql::Result<Vec<Arc<Conflict>>> {
            Ok(rt(ctx)?.conflicts.read().await.clone())
        }
    }

    pub struct Mutation;

    #[Object]
    impl Mutation {
        #[graphql(name = "renameKit")]
        async fn rename_kit(&self, ctx: &Context<'_>, #[graphql(name = "draftId")] draft_id: Id, #[graphql(name = "transactionId")] transaction_id: Id, name: String) -> async_graphql::Result<Id> {
            let rt = rt(ctx)?;
            let request_id = Id::new().await;
            rt.dispatch_wip(Command::RenameKit { request_id: request_id.clone(), draft_id, transaction_id, name }).await;
            Ok(request_id)
        }

        #[graphql(name = "changeDescription")]
        async fn change_description(&self, ctx: &Context<'_>, #[graphql(name = "draftId")] draft_id: Id, #[graphql(name = "transactionId")] transaction_id: Id, description: String) -> async_graphql::Result<Id> {
            let rt = rt(ctx)?;
            let request_id = Id::new().await;
            rt.dispatch_wip(Command::ChangeDescription { request_id: request_id.clone(), draft_id, transaction_id, description }).await;
            Ok(request_id)
        }

        #[graphql(name = "createFixedPiece")]
        async fn create_fixed_piece(
            &self,
            ctx: &Context<'_>,
            #[graphql(name = "draftId")] draft_id: Id,
            #[graphql(name = "transactionId")] transaction_id: Id,
            #[graphql(name = "designId")] design_id: Id,
            position: Position,
            name: Option<String>,
            description: Option<String>,
        ) -> async_graphql::Result<Id> {
            let rt = rt(ctx)?;
            let request_id = Id::new().await;
            // Skeleton: the GraphQL `createFixedPiece` does not yet take an explicit blueprint id;
            // we mint one so the piece always has a blueprint reference. A follow-up ticket adds the arg.
            let blueprint_id = Id::new().await;
            rt.dispatch_wip(Command::CreateFixedPiece { request_id: request_id.clone(), draft_id, transaction_id, design_id, blueprint_id, position, name, description }).await;
            Ok(request_id)
        }

        #[graphql(name = "fixPiece")]
        async fn fix_piece(
            &self,
            ctx: &Context<'_>,
            #[graphql(name = "draftId")] draft_id: Id,
            #[graphql(name = "transactionId")] transaction_id: Id,
            #[graphql(name = "designId")] design_id: Id,
            #[graphql(name = "pieceId")] piece_id: Id,
        ) -> async_graphql::Result<Id> {
            let rt = rt(ctx)?;
            let request_id = Id::new().await;
            rt.dispatch_wip(Command::FixPiece { request_id: request_id.clone(), draft_id, transaction_id, design_id, piece_id }).await;
            Ok(request_id)
        }
    }

    pub struct SubscriptionRoot;

    type SubStream<T> = std::pin::Pin<Box<dyn Stream<Item = T> + Send>>;

    macro_rules! sub_filter {
        ($ctx:ident, $variant:ident, $ty:ty) => {{
            let bus = bus($ctx)?.clone();
            let mut rx = bus.subscribe();
            let s: SubStream<$ty> = Box::pin(stream! {
                while let Ok(ev) = rx.recv().await {
                    if let Event::$variant(value) = ev { yield value; }
                }
            });
            Ok(s)
        }};
    }

    #[Subscription]
    impl SubscriptionRoot {
        #[graphql(name = "commandSucceeded")]
        async fn command_succeeded(&self, ctx: &Context<'_>) -> async_graphql::Result<SubStream<CommandReceipt>> {
            sub_filter!(ctx, CommandSucceeded, CommandReceipt)
        }

        #[graphql(name = "operationSucceeded")]
        async fn operation_succeeded(&self, ctx: &Context<'_>) -> async_graphql::Result<SubStream<OperationIface>> {
            let bus = bus(ctx)?.clone();
            let mut rx = bus.subscribe();
            let s: SubStream<OperationIface> = Box::pin(stream! {
                while let Ok(ev) = rx.recv().await {
                    match ev {
                        Event::CreatedFixedPiece(o) => yield OperationIface::CreatedFixedPiece(o),
                        Event::FixedPiece(o) => yield OperationIface::FixedPiece(o),
                        Event::DraggedPiece(o) => yield OperationIface::DraggedPiece(o),
                        Event::RenamedKit(o) => yield OperationIface::RenamedKit(o),
                        Event::ChangedDescription(o) => yield OperationIface::ChangedDescription(o),
                        _ => {}
                    }
                }
            });
            Ok(s)
        }

        #[graphql(name = "operationFailed")]
        async fn operation_failed(&self, ctx: &Context<'_>) -> async_graphql::Result<SubStream<ComposeError>> {
            sub_filter!(ctx, OperationFailed, ComposeError)
        }

        #[graphql(name = "kitRenamed")]
        async fn kit_renamed(&self, ctx: &Context<'_>) -> async_graphql::Result<SubStream<Arc<RenamedKit>>> {
            sub_filter!(ctx, RenamedKit, Arc<RenamedKit>)
        }

        #[graphql(name = "descriptionChanged")]
        async fn description_changed(&self, ctx: &Context<'_>) -> async_graphql::Result<SubStream<Arc<ChangedDescription>>> {
            sub_filter!(ctx, ChangedDescription, Arc<ChangedDescription>)
        }

        #[graphql(name = "createdFixedPiece")]
        async fn created_fixed_piece(&self, ctx: &Context<'_>) -> async_graphql::Result<SubStream<Arc<CreatedFixedPiece>>> {
            sub_filter!(ctx, CreatedFixedPiece, Arc<CreatedFixedPiece>)
        }

        #[graphql(name = "fixedPiece")]
        async fn fixed_piece(&self, ctx: &Context<'_>) -> async_graphql::Result<SubStream<Arc<FixedPiece>>> {
            sub_filter!(ctx, FixedPiece, Arc<FixedPiece>)
        }

        #[graphql(name = "draggedPiece")]
        async fn dragged_piece(&self, ctx: &Context<'_>) -> async_graphql::Result<SubStream<Arc<DraggedPiece>>> {
            sub_filter!(ctx, DraggedPiece, Arc<DraggedPiece>)
        }

        async fn error(&self, ctx: &Context<'_>) -> async_graphql::Result<SubStream<ComposeError>> {
            sub_filter!(ctx, OperationFailed, ComposeError)
        }
    }

    /// 🧱 Build the schema with the parent runtime + event bus injected as data.
    pub async fn build_schema() -> Schema<Query, Mutation, SubscriptionRoot> {
        let rt = ParentRuntime::spawn().await;
        let bus = rt.bus.clone();
        Schema::build(Query, Mutation, SubscriptionRoot).data(rt).data(bus).finish()
    }

    /// 📜 Convenience SDL for tests / tooling.
    pub async fn sdl() -> String {
        build_schema().await.sdl()
    }

    #[allow(dead_code)]
    fn _unused() -> EmptySubscription {
        EmptySubscription
    }
}

