    //! 🌿 Version-control entities — change/transaction/draft/checkpoint/alternative/graph/session/conflict.
    use std::sync::{Arc, Weak};

    use async_graphql::{Object, Union};
    use async_lock::RwLock;

    use crate::error::ComposeError;
