        async fn id(&self) -> Id {
            self.id.clone()
        }
        async fn hash(&self) -> String {
            self.compute_hash().await
        }
        /// Owner [`crate::vcs::Graph`] is set by [`crate::worker::ChildRuntime::new`] via Weak.
        async fn owner(&self) -> Option<Arc<crate::vcs::Graph>> {
