    /// 🛰️ Boot the parent runtime inside the current (parent) web worker.
    #[wasm_bindgen]
    pub async fn parent_boot() -> JsValue {
        let rt: Arc<ParentRuntime> = ParentRuntime::spawn().await;
        let _ = rt;
        JsValue::TRUE
    }

    /// 📜 Schema SDL for tooling.
