pub mod wasm_bridge {
    //! 🔌 Wires `ChildPort` ↔ `web_sys::Worker` postMessage on wasm32 targets.
    use std::sync::Arc;

    use wasm_bindgen::prelude::*;

    use crate::worker::ParentRuntime;

    #[wasm_bindgen(start)]
    pub fn _start() {
