    /// 📤 Writes the generated SDL to `COMPOSE_GRAPHQL_SCHEMA_OUT`; run via `npx nx build compose/graphql`.
    #[test]
    #[ignore = "writes the generated SDL to COMPOSE_GRAPHQL_SCHEMA_OUT"]
    fn export_compose_graphql_schema_file() {
        let out = std::env::var("COMPOSE_GRAPHQL_SCHEMA_OUT").expect("COMPOSE_GRAPHQL_SCHEMA_OUT");
        let path = std::path::PathBuf::from(out);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).expect("create schema output parent");
        }
        std::fs::write(path, block_on(crate::gql::sdl())).expect("write generated GraphQL schema");
    }

    #[test]
    fn parses_target_schema() {
        let sdl = block_on(crate::gql::sdl());
        for t in [
            "type Query",
            "type Mutation",
            "type Piece",
            "type Connector",
            "type Port",
            "type Connection",
            "type Design",
            "type Kit",
