            "type Session",
            "type Conflict",
            "type Checkpoint",
            "type Alternative",
            "type Draft",
            "type Transaction",
            "type Change",
            "type CreatedFixedPiece",
            "interface Operation",
            "scalar Timestamp",
        ] {
