tool_input.content:
//! 🦀 compose rust control plane — in-memory Arc-reference architecture.
//!
//! Every entity from `compose/graphql/target.schema.graphql` is one Rust struct shared as
//! `Arc<Self>` with interior `async_lock::RwLock` per mutable field. GraphQL resolvers take
//! `&self` on the entity (deref'd through the Arc) and return `Arc<Child>` for relationships,
//! so a query like `wip.theKit.design(id).piece(id).position` only acquires the locks it actually
//! needs and never deep-copies an aggregate Vec. There is exactly **one** `emit_event` in
//! the entire crate ([`event::EventBus::emit_event`]); every mutation routes through it.
//!
//! Worker topology: a parent router hosts the GraphQL schema and dispatches commands to two
//! child workers (`wip` + `authoritative`), each owning its own [`vcs::Graph`] as a shared
//! `Arc`. On native targets both children run as in-process async actors; on `wasm32` they
//! live in dedicated web workers wired through [`wasm_bridge`].

#![allow(clippy::new_without_default)]
#![allow(clippy::too_many_arguments)]
#![allow(dead_code)]

//#region 🆔 id

pub mod id {
    //! 🆔 Immutable uuid-v7 wrapper used by every entity.
    use async_graphql::{InputValueError, InputValueResult, Scalar, ScalarType, Value};
    use serde::{Deserialize, Serialize};
    use std::fmt;

    #[derive(Clone, Debug, Default, Eq, Hash, PartialEq, Serialize, Deserialize)]
    pub struct Id(pub String);

    impl Id {
        /// 🆕 Mint a fresh uuid-v7 (timestamped, monotonic).
        pub async fn new() -> Self {
            Self(uuid::Uuid::now_v7().to_string())
        }

        pub(crate) fn new_sync() -> Self {
            Self(uuid::Uuid::now_v7().to_string())
        }

        pub fn as_str(&self) -> &str {
            &self.0
        }
    }

    impl fmt::Display for Id {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            self.0.fmt(f)
        }
    }

    impl From<String> for Id {
        fn from(s: String) -> Self {
            Self(s)
        }
    }

    impl From<&str> for Id {
        fn from(s: &str) -> Self {
            Self(s.to_string())
        }
    }

    #[Scalar]
    impl ScalarType for Id {
        fn parse(value: Value) -> InputValueResult<Self> {
            match value {
                Value::String(s) => Ok(Self(s)),
                _ => Err(InputValueError::expected_type(value)),
            }
        }
        fn to_value(&self) -> Value {
            Value::String(self.0.clone())
        }
    }
}

//#endregion 🆔 id

//#region ⏱️ timestamp

pub mod timestamp {
    //! ⏱️ ISO-8601 millisecond-precision timestamp scalar.
    use async_graphql::{InputValueError, InputValueResult, Scalar, ScalarType, Value};
    use serde::{Deserialize, Serialize};

    #[derive(Clone, Debug, Default, Eq, PartialEq, Serialize, Deserialize)]
    pub struct Timestamp(pub String);

    #[Scalar]
    impl ScalarType for Timestamp {
        fn parse(value: Value) -> InputValueResult<Self> {
            match value {
                Value::String(s) => Ok(Self(s)),
                _ => Err(InputValueError::expected_type(value)),
            }
        }
        fn to_value(&self) -> Value {
            Value::String(self.0.clone())
        }
    }
}

//#endregion ⏱️ timestamp

//#region 🚨 error

pub mod error {
    //! 🚨 Crate-wide error type wired through the event bus as `OperationFailed`.
    use async_graphql::SimpleObject;
    use serde::{Deserialize, Serialize};
    use thiserror::Error;

    #[derive(Clone, Debug, Error, Serialize, Deserialize, SimpleObject)]
    #[graphql(name = "Error")]
    #[error("{kind}: {message}")]
    pub struct ComposeError {
        pub kind: String,
        pub message: String,
        pub request_id: Option<String>,
    }

    impl ComposeError {
        pub fn invalid<S: Into<String>>(msg: S) -> Self {
            Self { kind: "Invalid".to_string(), message: msg.into(), request_id: None }
        }
        pub fn not_found<S: Into<String>>(kind: S, id: S) -> Self {
            Self { kind: "NotFound".to_string(), message: format!("{}({})", kind.into(), id.into()), request_id: None }
        }
        pub fn with_request(mut self, id: crate::id::Id) -> Self {
            self.request_id = Some(id.0);
            self
        }
    }

    pub type Result<T> = std::result::Result<T, ComposeError>;
}

//#endregion 🚨 error

//#region 📐 geom

pub mod geom {
    //! 📐 Pure value geometry: vectors, points, planes, positions (Copy values; never Arc-wrapped).
    use async_graphql::{InputObject, SimpleObject};
    use serde::{Deserialize, Serialize};

    #[derive(Clone, Copy, Debug, Default, PartialEq, Serialize, Deserialize, SimpleObject, InputObject)]
    #[graphql(name = "Vector", input_name = "VectorInput")]
    pub struct Vector {
        pub x: f64,
        pub y: f64,
        pub z: f64,
    }

    #[derive(Clone, Copy, Debug, Default, PartialEq, Serialize, Deserialize, SimpleObject, InputObject)]
    #[graphql(name = "Point", input_name = "PointInput")]
    pub struct Point {
        pub x: f64,
        pub y: f64,
        pub z: f64,
    }

    #[derive(Clone, Copy, Debug, Default, PartialEq, Serialize, Deserialize, SimpleObject, InputObject)]
    #[graphql(name = "Coordinate", input_name = "CoordinateInput")]
    pub struct Coordinate {
        pub u: f64,
        pub v: f64,
    }

    #[derive(Clone, Copy, Debug, Default, PartialEq, Serialize, Deserialize, SimpleObject, InputObject)]
    #[graphql(name = "Offset", input_name = "OffsetInput")]
    pub struct Offset {
        pub u: f64,
        pub v: f64,
    }

    #[derive(Clone, Copy, Debug, Default, PartialEq, Serialize, Deserialize, SimpleObject, InputObject)]
    #[graphql(name = "Plane", input_name = "PlaneInput")]
    pub struct Plane {
        pub origin: Point,
        #[graphql(name = "xAxis")]
        pub x_axis: Vector,
        #[graphql(name = "yAxis")]
        pub y_axis: Vector,
    }

    #[derive(Clone, Copy, Debug, Default, PartialEq, Serialize, Deserialize, SimpleObject, InputObject)]
    #[graphql(name = "Position", input_name = "PositionInput")]
    pub struct Position {
        pub center: Coordinate,
        pub plane: Plane,
    }
}

//#endregion 📐 geom

//#region 🏷️ meta

pub mod meta {
    //! 🏷️ Strong shared metadata as plain SimpleObject value types (small, immutable).
    use async_graphql::SimpleObject;
    use serde::{Deserialize, Serialize};

    use crate::id::Id;
    use crate::timestamp::Timestamp;

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Location {
        pub id: Id,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct File {
        pub id: Id,
        pub url: String,
        pub mime: Option<String>,
        pub size: Option<i32>,
        pub hash: String,
        pub description: Option<String>,
        pub created: Option<Timestamp>,
        pub updated: Option<Timestamp>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Folder {
        pub id: Id,
        pub path: String,
        pub description: Option<String>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Author {
        pub id: Id,
        pub name: String,
        pub email: String,
        pub role: Option<String>,
        pub rank: Option<i32>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Attribute {
        pub id: Id,
        pub key: String,
        pub value: String,
        pub definition: Option<String>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Benchmark {
        pub id: Id,
        pub name: String,
        pub min: Option<f64>,
        pub max: Option<f64>,
        #[graphql(name = "minExcluded")]
        pub min_excluded: Option<bool>,
        #[graphql(name = "maxExcluded")]
        pub max_excluded: Option<bool>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Quality {
        pub id: Id,
        pub key: String,
        pub value: Option<String>,
        pub unit: Option<String>,
        pub definition: Option<String>,
        pub description: Option<String>,
        pub benchmarks: Vec<Benchmark>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Prop {
        pub id: Id,
        pub key: String,
        pub value: String,
        pub unit: Option<String>,
        pub quality: Option<Quality>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Tag {
        pub id: Id,
        pub name: String,
        pub order: Option<i32>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Concept {
        pub id: Id,
        pub name: String,
        pub description: Option<String>,
        pub order: Option<i32>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Stat {
        pub id: Id,
        pub key: String,
        pub value: String,
        pub unit: Option<String>,
        pub description: Option<String>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Layer {
        pub id: Id,
        pub name: String,
        pub description: Option<String>,
        pub color: Option<String>,
        pub order: Option<i32>,
        pub visible: Option<bool>,
        pub locked: Option<bool>,
    }

    #[derive(Clone, Debug, Default, Serialize, Deserialize, SimpleObject)]
    pub struct Group {
        pub id: Id,
