    /// 🔗 Untyped reference to one of the variants of the [`ChangeOwnerUnion`].
    #[derive(Clone)]
    pub enum ChangeOwnerRef {
        Transaction(Weak<Transaction>),
        Draft(Weak<Draft>),
        Checkpoint(Weak<Checkpoint>),
    }

    impl Default for Change {
