    }

    #[test]
    fn parses_target_schema() {
        let sdl = block_on(crate::gql::sdl());
        for t in [
            "type Query",
            "type Mutation",
            "type Piece",
            "type Connector",
            "type Port",
            "type Connection",
            "type Design",
            "type Kit",
            "type Graph",
            "type Session",
            "type Conflict",
            "type Checkpoint",
            "type Alternative",
            "type Draft",
            "type Transaction",
            "type Change",
            "type CreatedFixedPiece",
            "interface Operation",
            "scalar Timestamp",
        ] {
