pub mod gql {
    //! 🌐 GraphQL roots: Query / Mutation / Subscription + schema builder.
    use std::sync::Arc;

    use async_graphql::{Context, EmptySubscription, InputObject, Object, Schema, SimpleObject, Subscription};
    use async_stream::stream;
