        async fn rename_kit(&self, ctx: &Context<'_>, workspace: KitGraphWorkspace, #[graphql(name = "draftId")] draft_id: Id, #[graphql(name = "transactionId")] transaction_id: Id, name: String) -> async_graphql::Result<CommandReceipt> {
            let rt = rt(ctx)?;
