        }

        /// @emoji 🔢 Stable `projectionFingerprint` (blake3-style `hash::h`) keyed from graph + kit identity until piece-center sort lands.
        #[graphql(name = "projectionFingerprint")]
        async fn projection_fingerprint(&self) -> String {
